{
  "skill": {
    "name": "biage-premarket-analyzer",
    "display_name": "彪哥战法盘前分析",
    "version": "1.0.0",
    "description": "每日盘前自动获取全球市场数据，分析对A股的影响",
    "author": "彪哥战法团队",
    "language": "zh-CN"
  },
  "eastmoney_api": {
    "base_url": "https://push2.eastmoney.com/api/qt",
    "timeout": 30,
    "retry_times": 3,
    "retry_delay": 1
  },
  "markets": {
    "us": {
      "enabled": true,
      "indices": ["DJI", "IXIC", "SPX"],
      "names": {
        "DJI": "道琼斯",
        "IXIC": "纳斯达克",
        "SPX": "标普500"
      }
    },
    "hk": {
      "enabled": true,
      "indices": ["HSI", "HSCEI", "HSTECH"],
      "names": {
        "HSI": "恒生指数",
        "HSCEI": "国企指数",
        "HSTECH": "恒生科技"
      }
    },
    "asia": {
      "enabled": true,
      "indices": ["N225", "KS11", "AS51"],
      "names": {
        "N225": "日经225",
        "KS11": "韩国KOSPI",
        "AS51": "澳洲ASX200"
      }
    },
    "commodity": {
      "enabled": true,
      "items": ["CL", "GC", "HG"],
      "names": {
        "CL": "原油",
        "GC": "黄金",
        "HG": "铜"
      }
    }
  },
  "analysis": {
    "thresholds": {
      "major_event": 2.0,
      "significant_move": 3.0,
      "commodity_major": 3.0
    },
    "sectors": {
      "beneficiaries": {
        "科技": ["IXIC", "HSTECH"],
        "能源": ["CL"],
        "黄金": ["GC"],
        "有色": ["HG"]
      },
      "damaged": {
        "航空": ["CL"],
        "航运": ["CL"]
      }
    }
  },
  "output": {
    "timezone": "Asia/Shanghai",
    "language": "zh-CN",
    "format": "text",
    "save_history": true,
    "history_path": "./reports/"
  },
  "schedule": {
    "enabled": false,
    "cron": "0 8 * * 1-5",
    "description": "周一至周五上午8:00自动运行"
  }
}
